SELECT
    COUNT(*) AS TOPLAM_PERSONEL,
    COUNT(DISTINCT TCKN) AS FARKLI_TCKN,
    COUNT(DISTINCT TELEFONNO) AS FARKLI_TELEFON,
    COUNT(DISTINCT EPOSTA) AS FARKLI_EPOSTA,
    COUNT(DISTINCT KAYITOLUSTURMATARIHI) AS FARKLI_TARIH,
    COUNT(DISTINCT ROL) AS FARKLI_ROL
